// D131 (#339/#340/#341/#325), PLAN-OK-hist-data-fix, and D120.
// Acceptance authored before the data repair. Source dates are not game-time anchors.
// Run without a database or model; freshness tests separately verify generated bytes.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';
import test from 'node:test';
import lib from '../transport-health-recreation/scripts/lib.cjs';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
const HISTORY = 'history-events-knowledge';
const TRANSPORT = 'transport-health-recreation';
const read = relative => fs.readFileSync(path.join(ROOT, relative), 'utf8');
const csv = relative => lib.loadCsvObjects(path.join(ROOT, relative), ',');
const rowById = (rows, key, id) => {
  const found = rows.filter(row => row[key] === id);
  assert.equal(found.length, 1, `${id}: exactly one preserved record required`);
  return found[0];
};
const matchAll = (text, patterns, context) => {
  for (const pattern of patterns) assert.match(text, pattern, `${context}: missing caveat ${pattern}`);
};
const UNKNOWN = /не\s+(?:установ|извест|подтвержд|засвидетельств)|неизвест|неопредел|пробел/iu;
const BOOK_LEVEL = new Set(['B', 'C', 'D']);

const phases = csv(`${HISTORY}/historical_events/event_phases.csv`);
const figures = csv(`${HISTORY}/historical_figures/figures.csv`);
const recreation = csv(`${TRANSPORT}/recreation_culture/recreation_entities.csv`);
const health = csv(`${TRANSPORT}/health_body/health_entities.csv`);
const evidence = csv(`${TRANSPORT}/sources/book_evidence_transport_health_recreation.csv`);

test('#339: source precision replaces invented timestamps in the five phases', () => {
  const event = phases.filter(row => row.ev_id === 'nov_hist_1230_004');
  assert.equal(event.length, 5);
  // book:301539 §4366 and book:667380 §486 disagree on departure (8/9 December).
  // Background/aftermath are reconstructed stages, not exact attested dates.
  const dates = { background: '1230', omens: '1230-12', escalation: '1230-12-09',
    impact: '1230-12-30', aftermath: '1231' };
  for (const [phase, date] of Object.entries(dates)) {
    const row = rowById(event, 'phase', phase);
    assert.equal(row.date_range, date, `${phase}: precision supported by the approved source set`);
    assert.equal(row.is_game_time_anchor, 'false', `${phase}: no invented exact game time`);
    assert.ok(BOOK_LEVEL.has(row.confidence), `${phase}: secondary evidence cannot claim A`);
  }
  for (const phase of ['background', 'aftermath']) {
    const row = rowById(event, 'phase', phase);
    assert.ok(['C', 'D'].includes(row.confidence), `${phase}: reconstructed stage is not book-attested`);
    assert.match(row.audit_note, /реконструк|не\s+(?:установ|подтвержд|извест)|неизвест/iu);
  }
});

test('#339: geography and the departure-date conflict survive in the record', () => {
  const events = csv(`${HISTORY}/historical_events/events.csv`);
  const event = rowById(events, 'ev_id', 'nov_hist_1230_004');
  assert.match(event.event_title, /Новгород/iu);
  assert.doesNotMatch(event.event_title, /торжокск\p{L}*\s+расправ/iu);
  for (const row of phases.filter(row => row.ev_id === event.ev_id)) {
    assert.match(row.event_title, /Новгород/iu);
    assert.doesNotMatch(row.rumors, /торжокск\p{L}*\s+расправ/iu);
  }
  const departure = rowById(phases, 'phase_id', 'nov_hist_1230_004_omens');
  matchAll(`${departure.chronicle_ref} ${departure.audit_note} ${departure.source_refs}`,
    [/8/u, /9/u, /301539/u, /667380/u, /расхожд|разноглас|противореч|конфликт|разн\p{L}*\s+дат/iu], 'departure');
  const murder = rowById(phases, 'phase_id', 'nov_hist_1230_004_escalation');
  assert.match(murder.source_refs, /book:301539/u);
  assert.match(`${murder.summary} ${murder.historical_context}`, /Сем[её]н\p{L}*[\s\S]*Новгород|Новгород[\s\S]*Сем[её]н/iu);
  assert.match(rowById(phases, 'phase_id', 'nov_hist_1230_004_impact').source_refs, /book:667380/u);
});

test('#340: Yaroslav has an attested start and no invented end', () => {
  const row = rowById(figures, 'hf_id', 'hf_sql_r03');
  assert.equal(row.office_start, '1230-12-30');
  assert.equal(row.office_end, '', 'the start of Alexander\'s reign does not establish Yaroslav\'s last day');
  matchAll(row.note, [/1236/u, /1246/u, UNKNOWN], 'hf_sql_r03');
  matchAll(row.source_refs, [/book:378072/u, /book:566840/u, /book:667380/u], 'hf_sql_r03 sources');
  assert.ok(BOOK_LEVEL.has(row.confidence));
});

test('#340: Alexander retains the known month without a fictitious continuous office window', () => {
  const row = rowById(figures, 'hf_id', 'hf_sql_r05');
  assert.equal(row.office_start, '', 'January does not establish 1 January');
  assert.equal(row.office_end, '', 'disjoint draft periods cannot establish a continuous office ending in 1250');
  matchAll(`${row.period_note} ${row.note}`, [/январ/iu, /1231/u, /наместник/iu, UNKNOWN], 'hf_sql_r05');
  assert.doesNotMatch(row.period_note, /конец\s+1230/iu);
  assert.match(row.source_refs, /book:566840/u);
  assert.ok(BOOK_LEVEL.has(row.confidence));
});

test('#340: Mikita retains December without an invented election day or end', () => {
  const row = rowById(figures, 'hf_id', 'hf_sql_r09');
  assert.equal(row.office_start, '');
  assert.equal(row.office_end, '');
  matchAll(`${row.period_note} ${row.note}`, [/декабр/iu, /1230/u, UNKNOWN], 'hf_sql_r09');
  assert.match(row.source_refs, /book:667380/u);
  assert.ok(BOOK_LEVEL.has(row.confidence));
});

// book:624953 §§1100–1162. Match meaning-bearing caveats, never an entire authored sentence.
// Four existing caveats remain green; eleven missing qualifications should fail before repair.
const caveats = {
  rec_001: [/1230/u, /не актуальн|не\s+(?:для|относится)|исчез/iu],
  rec_002: [/X\s*в/u, /Киев/iu, /Чернигов/iu, /Ладог/iu, /Гн[её]здов/iu,
    /Новгород/iu, /1230/u, /не локальн|не\s+(?:подтвержд|засвидетельств)/iu,
    /(?:групп|описан|огранич)\p{L}*[\s\S]*находк|не[\s\S]*(?:люб|вс)[\s\S]*кост/iu],
  rec_003: [/правил/iu, /реконструк|аналог/iu, /этнограф/iu],
  rec_004: [/атрибуц|фишк|кружк/iu, /предполож|возможн/iu, /комплект|вид/iu, UNKNOWN],
  rec_005: [/Новгород/iu, /(?:2[-–]?й\s*пол|втор\p{L}*\s+половин)[\s\S]*XIII/iu, /1230/u, /редк|сомнит/iu],
  rec_006: [/археолог/iu, /X\s*в/u, /этнограф|Дал/iu, UNKNOWN, /Новгород/iu, /1230/u],
  rec_007: [/обобщ|древнерусск/iu, /доля|часть|самодел/iu, /Новгород/iu, /1230/u, UNKNOWN],
  rec_008: [/домонгольск/iu, /Руси/iu, /тип/iu, UNKNOWN, /Новгород/iu, /1230/u],
  rec_009: [/Новгород/iu, /X[\s\S]*XI/u, /поздн[\s\S]*реже|реже[\s\S]*поздн/iu, /Стар\p{L}*\s+Ладог/iu],
  rec_010: [/Новгород/iu, /стрел/iu, /датиров|дат[аы]|сло[йя]/iu,
    /лук/iu, /размер|материал/iu, UNKNOWN],
  rec_011: [/XI[–—-]XIII/u, /1230/u, /внутри|границ|не\s+установ/iu],
  rec_012: [/Новгород/iu, /XIII/u, /форм|вид/iu, /1230/u, /не\s+(?:устанавлива|установ|подтвержд)|неизвест/iu],
  rec_013: [/XI[–—-]XIII/u, /Ладог/iu, /Новгород/iu, /Белоозер/iu, /редк/iu, /1230/u, UNKNOWN],
  rec_014: [/Новгород/iu, /разн\p{L}*\s+горизонт/iu, /1230/u, UNKNOWN,
    /одежд[\s\S]*не\s+(?:наход|найд)|не\s+(?:наход|найд)[\s\S]*одежд/iu, /домонгольск/iu],
  rec_015: [/Новгород/iu, /XII[–—-]XIII/u, /1230/u, UNKNOWN],
};
for (const [id, patterns] of Object.entries(caveats)) {
  test(`#341: ${id} carries its temporal/regional qualification`, () => {
    const row = rowById(recreation, 'rc_id', id);
    matchAll(row.notes, patterns, id);
    assert.match(row.source_refs, /book:624953/u);
    const facts = evidence.filter(fact => fact.domain === 'recreation_culture' && fact.entity_ru === row.name_ru);
    assert.ok(facts.length > 0, `${id}: preserved source grouping`);
    for (const fact of facts.filter(fact => fact.note)) {
      assert.ok(row.notes.includes(fact.note), `${id}: source caveat was lost: ${fact.note}`);
    }
  });
}

test('#341: the already repaired older fifteen-record scope stays qualified', () => {
  const older = ['rec_005', 'rec_056', 'rec_036', 'rec_049', 'rec_050', 'rec_051', 'rec_052',
    'rec_053', 'rec_016', 'rec_017', 'rec_022', 'rec_024', 'rec_040', 'rec_045', 'rec_047'];
  for (const id of older) {
    const row = rowById(recreation, 'rc_id', id);
    assert.match(row.notes, /1230/u, `${id}: retained dating qualification`);
    const notes = evidence.filter(fact => fact.domain === 'recreation_culture' && fact.entity_ru === row.name_ru)
      .map(fact => fact.note).filter(Boolean);
    assert.ok(notes.length > 0, `${id}: existing source qualifications`);
    for (const note of notes) assert.ok(row.notes.includes(note), `${id}: lost existing source note`);
  }
  for (const id of ['rec_036', 'rec_049']) {
    const row = rowById(recreation, 'rc_id', id);
    matchAll(row.anachronism_flag, [/Костомаров/iu, /друг|отдельн/iu, /c1230/u], id);
  }
});

const HEALTH_FIELDS = ['hl_id', 'kind', 'name_ru', 'facts_summary', 'period_care_practice_note',
  'period', 'fact_count', 'source_refs', 'confidence', 'status'];
test('#325: Smolensk mor is region-qualified with three explicit source gaps and no schema expansion', () => {
  const row = rowById(health, 'hl_id', 'hlb_020');
  assert.deepEqual(Object.keys(row), HEALTH_FIELDS);
  assert.match(row.facts_summary, /Смоленск/iu);
  assert.equal(row.period, 'c1230');
  assert.equal(row.confidence, 'B');
  assert.match(row.source_refs, /book:886616[\s\S]*¶15/u);
  matchAll(row.period_care_practice_note, [/Смоленск/iu,
    /не[\s\S]*(?:Новгород|перенос)|Новгород[\s\S]*не/iu], 'hlb_020 regional limit');
  for (const field of ['course_stages', 'visible_signs', 'season_risk']) {
    // Each named field needs its own nearby unknown/gap marker, not one disclaimer elsewhere.
    const start = row.period_care_practice_note.indexOf(field);
    assert.ok(start >= 0, `hlb_020: missing ${field} source gap`);
    assert.match(row.period_care_practice_note.slice(start + field.length).split(/[;.|]/u)[0], UNKNOWN, field);
  }
});

test('#325: health README separates the Smolensk event from Novgorod famine and states clinical gaps', () => {
  const text = read(`${TRANSPORT}/health_body/README.md`);
  const paragraphs = text.split(/\n\s*\n/u);
  const regional = paragraphs.filter(paragraph => /Смоленск/iu.test(paragraph)).join('\n');
  matchAll(regional, [/1230/u, /Новгород/iu, /не\s+(?:относ|перенос|тождествен|означа)|отдельн|отлич|не\s+Новгород/iu], 'health README region');
  const gaps = paragraphs.filter(paragraph => /hlb_020|смоленск/iu.test(paragraph)).join('\n');
  matchAll(gaps, [/course_stages/u, /visible_signs/u, /season_risk/u, UNKNOWN], 'hlb_020 README gaps');
  assert.doesNotMatch(text, /Мор\s+1230[–—-]31[\s\S]{0,100}голодный\s+мор[\s\S]{0,150}«мор\s+1230\s+г\./iu,
    'README must not list the Smolensk entity as the Novgorod famine mor');
});

test('D120: actual health records recognize Cyrillic mor while retaining animal disease', () => {
  const expected = { hlb_019: 'epidemic', hlb_020: 'epidemic', hlb_021: 'epidemic',
    hlb_031: 'epidemic', hlb_032: 'epidemic', hlb_047: 'animal_disease' };
  for (const [id, kind] of Object.entries(expected)) {
    assert.equal(rowById(health, 'hl_id', id).kind, kind, `${id}: ${kind} classification of a real record`);
  }
});

test('D120: the actual health builder emits correct kinds without writing files', () => {
  const filename = path.join(ROOT, TRANSPORT, 'health_body/scripts/build.cjs');
  const require = createRequire(filename);
  let generated;
  // Exercise the unchanged production entry point and real evidence; intercept only its CSV writer.
  vm.runInNewContext(fs.readFileSync(filename, 'utf8'), {
    __dirname: path.dirname(filename),
    require: name => name === '../../scripts/lib.cjs'
      ? { ...lib, writeCsv(_file, fields, rows) {
        assert.equal(generated, undefined, 'one health output');
        assert.deepEqual(Array.from(fields), HEALTH_FIELDS);
        generated = rows;
      } } : require(name),
    console: { error() {} },
  }, { filename, timeout: 5000 });
  assert.ok(generated, 'health builder must emit its real rows');
  for (const [id, kind] of Object.entries({ hlb_019: 'epidemic', hlb_020: 'epidemic',
    hlb_021: 'epidemic', hlb_031: 'epidemic', hlb_032: 'epidemic', hlb_047: 'animal_disease' })) {
    assert.equal(rowById(generated, 'hl_id', id).kind, kind, `${id}: real builder classification`);
  }
});
